import { defineSchedule } from "eve/schedules";
import { noteDeliveryFailure, tick } from "@kybernesis/magic/steps";
import { deliver } from "../lib/magic-surfaces.js";

// Every five minutes, code looks at each opted-in person's calendar, mail and
// reminders. The model only runs when that finds something worth saying, and
// then as the person, in the conversation they already have with this agent.
export default defineSchedule({
  cron: "*/5 * * * *",
  async run({ to, waitUntil }) {
    for (const dispatch of await tick()) {
      waitUntil(deliver(to, dispatch).catch((error) => noteDeliveryFailure(dispatch.principalId, error)));
    }
  },
});

import type { MagicDispatch } from "@kybernesis/magic";
import type { ScheduleToFn } from "eve/schedules";
import kyb from "../channels/kyb.js";

/**
 * Where a heads-up is delivered: the conversation the person last used.
 *
 * Studio and the phone app share the agent's canonical conversation through
 * the kyb channel, and a turn run as the person rings their phone. To deliver
 * into another channel's conversation, import that channel and add a branch
 * on the recorded address. For iMessage through Linq:
 *
 *   import linq from "../channels/linq.js";
 *   if (dispatch.surface.token?.startsWith("linq:")) {
 *     return to(linq, { threadId: dispatch.surface.token }).send(dispatch.packet, { auth: dispatch.surface.auth });
 *   }
 */
export function deliver(to: ScheduleToFn, dispatch: MagicDispatch) {
  return to(kyb, { routine: "magic" }).send(dispatch.packet, { auth: dispatch.surface.auth });
}

import { magicHook } from "@kybernesis/magic/tools";

// Remembers which conversation each person last wrote in, so their heads-ups
// land there. Only verified people are recorded; magic's own turns are not.
export default magicHook();

import { magicSettingsTool } from "@kybernesis/magic/tools";

// Heads-ups for the person in this turn: on, off, and how they work.
export default magicSettingsTool();

import { remindMeTool } from "@kybernesis/magic/tools";

// One person's one-off reminder, delivered into their conversation on time.
export default remindMeTool();

import { magicStatusTool } from "@kybernesis/magic/tools";

// What heads-ups are doing for the person in this turn, and why.
export default magicStatusTool();

import { magicFeedbackTool } from "@kybernesis/magic/tools";

// "Fewer of these", "stop the X ones": the person's dial on each kind.
export default magicFeedbackTool();

import { noReply } from "eve/tools/no_reply";

// Lets a background check end in silence when nothing is worth saying.
export default noReply();

import { magicInstructions } from "@kybernesis/magic/tools";

// How heads-ups work, plus what this agent told the person on its own lately.
export default magicInstructions();
